from fractions import Fraction
import math

def reducible(n):
    # f(x) = 3x^3 - n x - n - 2; check rational roots p/q, p|(n+2), q|3
    c = n + 2
    cands = set()
    for p in range(-abs(c)-1, abs(c)+2):
        if p == 0 and c == 0:
            continue
        if c == 0:
            # root 0 possible
            cands.add(Fraction(0))
            break
        if p != 0 and c % p == 0:
            for q in (1, 3):
                cands.add(Fraction(p, q))
    # also include p=0 only if c==0
    for r in cands:
        if 3*r**3 - n*r - n - 2 == 0:
            return True
    return False

# brute force n in a wide range
sols = []
for n in range(-200000, 200001):
    if reducible(n):
        sols.append(n)
print(sols)
print(sum(sols))
